<?php
/**
 * File for the language switcher element in Bricks.
 *
 * @package easy-language
 */

namespace easyLanguage\PageBuilder\Bricks;

// prevent direct access.
defined( 'ABSPATH' ) || exit;

use Bricks\Element;
use easyLanguage\EasyLanguage\Switcher;

/**
 * Object for the language switcher element in Bricks.
 *
 * The settings are generated from the field definitions of the switcher, the output is generated by the switcher.
 *
 * @noinspection PhpUnused
 */
class Switcher_Element extends Element {
	/**
	 * The category of this element in the Bricks editor.
	 *
	 * @var string
	 */
	public $category = 'WordPress';

	/**
	 * The name of this element.
	 *
	 * @var string
	 */
	public $name = 'easy-language-switcher';

	/**
	 * The icon of this element: the Easy Language logo via the style "easy-language-builder-icon".
	 *
	 * @var string
	 */
	public $icon = 'easy-language-builder-icon';

	/**
	 * Return the label of this element.
	 *
	 * @return string
	 */
	public function get_label(): string {
		return __( 'Language Switcher', 'easy-language' );
	}

	/**
	 * Return the keywords for the search in the Bricks editor.
	 *
	 * @return array<int,string>
	 */
	public function get_keywords(): array {
		return array( __( 'Easy Language', 'easy-language' ), __( 'Menu', 'easy-language' ), 'language', 'switcher' );
	}

	/**
	 * Set the control groups: one group per section of the switcher settings.
	 *
	 * @return void
	 */
	public function set_control_groups(): void {
		$fields = Switcher::get_instance()->get_widget_fields();
		foreach ( Switcher::get_instance()->get_widget_sections() as $section => $title ) {
			$this->control_groups[ $section ] = array(
				'title' => $title,
				'tab'   => 'design' === $section ? 'style' : 'content',
			);

			// hide the group if all its fields have the same condition (e.g. the design of the toggle).
			$conditions = array();
			foreach ( $fields as $field ) {
				if ( ( $field['section'] ?? 'settings' ) === $section ) {
					$conditions[] = wp_json_encode( $field['condition'] ?? array() );
				}
			}
			$conditions = array_unique( $conditions );
			if ( 1 === count( $conditions ) ) {
				$required = $this->get_required( json_decode( (string) reset( $conditions ), true ) );
				if ( ! empty( $required ) ) {
					$this->control_groups[ $section ]['required'] = $required;
				}
			}
		}
	}

	/**
	 * Set the controls from the field definitions of the switcher.
	 *
	 * @return void
	 */
	public function set_controls(): void {
		$sections = Switcher::get_instance()->get_widget_sections();

		foreach ( Switcher::get_instance()->get_widget_fields() as $name => $field ) {
			$section = isset( $field['section'] ) && isset( $sections[ $field['section'] ] ) ? $field['section'] : 'settings';

			// collect the basic settings of this control.
			$control = array(
				'group'    => $section,
				'tab'      => 'design' === $section ? 'style' : 'content',
				'label'    => $field['label'],
				'rerender' => true,
			);
			if ( ! empty( $field['description'] ) ) {
				$control['description'] = $field['description'];
			}

			// add the settings depending on the type.
			switch ( $field['type'] ) {
				case 'select':
					$options         = (array) ( $field['options'] ?? array() );
					$control['type'] = 'select';

					// an option with empty value is used as placeholder as Bricks uses an empty value for "not set".
					if ( isset( $options[''] ) ) {
						$control['placeholder'] = $options[''];
						unset( $options[''] );
					}
					$control['options'] = $options;
					break;

				case 'switch':
					$control['type'] = 'checkbox';
					break;

				case 'size':
					$control['type']  = 'number';
					$control['units'] = $this->get_units( (array) ( $field['units'] ?? array( 'px' ) ) );
					break;

				case 'color':
					$control['type'] = 'color';
					break;

				case 'objects':
					$control['type']        = 'select';
					$control['multiple']    = true;
					$control['searchable']  = true;
					$control['optionsAjax'] = array(
						'action' => 'easy_language_bricks_objects',
					);
					if ( ! empty( $field['description'] ) ) {
						$control['placeholder'] = $field['description'];
						unset( $control['description'] );
					}
					break;

				default:
					$control['type'] = 'text';
			}

			// set the default value (empty values are the default of Bricks).
			if ( ! empty( $field['default'] ) ) {
				$control['default'] = $field['default'];
			}

			// add the conditions.
			$required = $this->get_required( $field['condition'] ?? array() );
			if ( ! empty( $required ) ) {
				$control['required'] = $required;
			}

			// add the control.
			$this->controls[ $name ] = $control;
		}
	}

	/**
	 * Return the conditions of a field in the format of Bricks ("required").
	 *
	 * @param mixed $condition The conditions of the field definition (field => allowed values).
	 *
	 * @return array<int,array<int,mixed>>
	 */
	private function get_required( mixed $condition ): array {
		$required = array();
		if ( ! is_array( $condition ) ) {
			return $required;
		}
		foreach ( $condition as $condition_field => $values ) {
			$required[] = array( (string) $condition_field, '=', array_values( (array) $values ) );
		}
		return $required;
	}

	/**
	 * Return the unit definitions for a number control.
	 *
	 * @param array<int|string,mixed> $units List of units.
	 *
	 * @return array<string,array<string,int|float>>
	 */
	private function get_units( array $units ): array {
		$list = array();
		foreach ( $units as $unit ) {
			$unit          = (string) $unit;
			$list[ $unit ] = 'px' === $unit
				? array(
					'min'  => 0,
					'max'  => 128,
					'step' => 1,
				)
				: array(
					'min'  => 0,
					'max'  => '%' === $unit ? 50 : 8,
					'step' => '%' === $unit ? 1 : 0.1,
				);
		}
		return $list;
	}

	/**
	 * Render the element in frontend and in the Bricks editor.
	 *
	 * @return void
	 */
	public function render(): void {
		$switcher = Switcher::get_instance();
		$settings = is_array( $this->settings ) ? $this->settings : array();

		// collect the values and convert the Bricks color values to CSS colors.
		$values = array();
		foreach ( $switcher->get_widget_fields() as $name => $field ) {
			if ( ! isset( $settings[ $name ] ) ) {
				continue;
			}
			$values[ $name ] = 'color' === $field['type'] ? $this->get_color( $settings[ $name ] ) : $settings[ $name ];
		}

		// get the output.
		$is_editor = $this->is_editor();
		$html      = $switcher->render_widget( $values, 'bricks', $is_editor );

		// show a placeholder in the editor if there is no output.
		if ( empty( $html ) ) {
			if ( $is_editor ) {
				echo $this->render_element_placeholder( array( 'title' => __( 'Language Switcher', 'easy-language' ) ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
			}
			return;
		}

		// output the switcher in the wrapper with the attributes of Bricks (id, classes, custom attributes).
		echo '<div ' . $this->render_attributes( '_root' ) . '>' . $html . '</div>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
	}

	/**
	 * Return whether the actual request is the Bricks editor or its preview.
	 *
	 * @return bool
	 */
	private function is_editor(): bool {
		return ( function_exists( 'bricks_is_builder_call' ) && bricks_is_builder_call() )
			|| ( function_exists( 'bricks_is_builder_iframe' ) && bricks_is_builder_iframe() )
			|| ( function_exists( 'bricks_is_builder_main' ) && bricks_is_builder_main() );
	}

	/**
	 * Return the CSS color of a Bricks color value.
	 *
	 * Bricks saves colors as array with "hex", "rgb", "raw" (e.g. CSS variables) and "id" (global color).
	 *
	 * @param mixed $value The value.
	 *
	 * @return string
	 */
	private function get_color( mixed $value ): string {
		if ( is_string( $value ) ) {
			return $value;
		}
		if ( ! is_array( $value ) ) {
			return '';
		}
		foreach ( array( 'raw', 'rgb', 'hex' ) as $key ) {
			if ( ! empty( $value[ $key ] ) && is_string( $value[ $key ] ) ) {
				return $value[ $key ];
			}
		}
		if ( ! empty( $value['id'] ) && is_string( $value['id'] ) ) {
			return 'var(--bricks-color-' . sanitize_key( $value['id'] ) . ')';
		}
		return '';
	}
}
